def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def nearest_target(targets, sx, sy):
        best = None
        best_d = None
        for t in targets:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    env = observation.get("environment_name", "") or ""
    self_pos = pos(observation.get("self_position", (0, 0)))
    sx, sy = self_pos
    ox, oy = pos(observation.get("opponent_position", self_pos), self_pos)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    role = observation.get("self_role", "")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return [clamp_step(ox - sx), clamp_step(oy - sy)]
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = corners[0]
        best_d = -1
        for c in corners:
            d = abs(c[0] - ox) + abs(c[1] - oy)
            if d > best_d:
                best_d = d
                target = c
        return [clamp_step(target[0] - sx), clamp_step(target[1] - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        target = nearest_target(targets or [], sx, sy)
        if target is None:
            return [clamp_step(ox - sx), clamp_step(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]
        return [clamp_step(target[0] - sx), clamp_step(target[1] - sy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest_target(resources, sx, sy)
    if target is not None:
        return [clamp_step(target[0] - sx), clamp_step(target[1] - sy)]

    enemies = observation.get("opponents") or []
    if enemies:
        enemy = nearest_target(enemies, sx, sy)
        if enemy is not None:
            return [clamp_step(enemy[0] - sx), clamp_step(enemy[1] - sy)]

    if ox == sx and oy == sy:
        return [0, 0]
    return [clamp_step(ox - sx), clamp_step(oy - sy)]

